59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
66	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
67	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    /**
106	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
107	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
108	     */
109	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
110	        List<String> missing = new ArrayList<>();
111	        if (isBlank(ownerFieldsDto.getFirstName())) {
112	            missing.add("firstName");
113	        }
114	        if (isBlank(ownerFieldsDto.getLastName())) {
115	            missing.add("lastName");
116	        }
117	        if (isBlank(ownerFieldsDto.getAddress())) {
118	            missing.add("address");
119	        }
120	        if (isBlank(ownerFieldsDto.getCity())) {
121	            missing.add("city");
122	        }
123	        if (isBlank(ownerFieldsDto.getTelephone())) {
124	            missing.add("telephone");
125	        }
126	        if (!missing.isEmpty()) {
127	            throw new RequiredFieldsMissingException(missing);
128	        }
129	    }
130	
131	    private static boolean isBlank(String value) {
132	        return value == null || value.isBlank();
133	    }
134	
135	    /**
136	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
137	     * A leading {@code +} and its country code are kept as given; otherwise the country code
138	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
139	     * The result must carry 8 to 15 digits after the {@code +}. Returns the E.164 string to be
140	     * stored and returned.
141	     *
142	     * @param telephone the raw telephone as supplied by the caller
143	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
144	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
145	     */
146	    private static String normalizeTelephone(String telephone) {
147	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
148	        String e164;
149	        if (cleaned.startsWith("+")) {
150	            e164 = "+" + cleaned.substring(1);
151	        } else {
152	            String national = cleaned;
153	            if (national.startsWith("0")) {
154	                national = national.substring(1);
155	            }
156	            e164 = "+61" + national;
157	        }
158	        String digits = e164.substring(1);
159	        if (!digits.matches("\\d{8,15}")) {
160	            throw new InvalidTelephoneException(
161	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
162	        }
163	        return e164;
164	    }
165	
166	    /**
167	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
168	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
169	     *
170	     * @param email the raw email as supplied by the caller, may be {@code null}
171	     * @return the lower-cased email, or {@code null} when none was supplied
172	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
173	     */
174	    private static String normalizeEmail(String email) {
175	        if (email == null || email.isBlank()) {
176	            return null;
177	        }
178	        String trimmed = email.trim();
179	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
180	            throw new InvalidEmailException("Email must be a syntactically valid address");
181	        }
182	        return trimmed.toLowerCase(Locale.ROOT);
183	    }
184	
185	    /**
186	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
187	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
188	     * direct equality comparison of the E.164 values against the stored values is sufficient.
189	     *
190	     * @param normalizedTelephone the E.164 telephone of the owner being created
191	     * @throws DuplicateTelephoneException if another owner already uses this telephone
192	     */
193	    private void rejectDuplicateTelephone(String normalizedTelephone) {
194	        boolean inUse = this.clinicService.findAllOwners().stream()
195	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
196	        if (inUse) {
197	            throw new DuplicateTelephoneException(
198	                "Telephone is already used by another owner");
199	        }
200	    }
201	
202	    /**
203	     * Builds the customer code assigned to an owner on create, formatted {@code '<LAST3>-<NNNN>'}
204	     * where {@code LAST3} is the upper-cased first three letters of the owner's last name and
205	     * {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than the current
206	     * number of owners, e.g. {@code 'SMI-0007'}.
207	     *
208	     * @param lastName the last name of the owner being created
209	     * @return the formatted customer code
210	     */
211	    private String nextCustomerCode(String lastName) {
212	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
213	        int sequence = this.clinicService.findAllOwners().size() + 1;
214	        return String.format("%s-%04d", last3, sequence);
215	    }
