217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner == null) {
222	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	        }
224	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
230	        validateRequiredFields(ownerFieldsDto);
231	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
232	        rejectDuplicateTelephone(normalizedTelephone);
233	        ownerFieldsDto.setTelephone(normalizedTelephone);
234	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
235	        if (ownerFieldsDto.getRegistrationDate() == null) {
236	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
237	        }
238	        HttpHeaders headers = new HttpHeaders();
239	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
240	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getLastName()));
241	        this.clinicService.saveOwner(owner);
242	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
243	        headers.setLocation(UriComponentsBuilder.newInstance()
244	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
245	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Override
250	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
251	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
252	        if (currentOwner == null) {
253	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	        }
255	        currentOwner.setAddress(ownerFieldsDto.getAddress());
256	        currentOwner.setCity(ownerFieldsDto.getCity());
257	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
258	        currentOwner.setLastName(ownerFieldsDto.getLastName());
259	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
260	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
261	        this.clinicService.saveOwner(currentOwner);
262	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
263	    }
264	
265	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
266	    @Transactional
267	    @Override
268	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
269	        Owner owner = this.clinicService.findOwnerById(ownerId);
270	        if (owner == null) {
271	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
272	        }
273	        this.clinicService.deleteOwner(owner);
274	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Override
279	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
280	        Owner owner = this.clinicService.findOwnerById(ownerId);
281	        if (owner == null) {
282	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	        }
284	        HttpHeaders headers = new HttpHeaders();
285	        Pet pet = petMapper.toPet(petFieldsDto);
286	        owner.setId(ownerId);
287	        pet.setOwner(owner);
288	        pet.getType().setName(null);
289	        this.clinicService.savePet(pet);
290	        PetDto petDto = petMapper.toPetDto(pet);
291	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
292	            .buildAndExpand(pet.getId()).toUri());
293	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
294	    }
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
299	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
300	        if (currentOwner != null) {
301	            Pet currentPet = this.clinicService.findPetById(petId);
302	            if (currentPet != null) {
303	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
304	                currentPet.setName(petFieldsDto.getName());
305	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
306	                this.clinicService.savePet(currentPet);
307	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
308	            }
309	        }
310	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
311	    }
312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Override
315	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
316	        HttpHeaders headers = new HttpHeaders();
317	        Visit visit = visitMapper.toVisit(visitFieldsDto);
318	        Pet pet = new Pet();
319	        pet.setId(petId);
320	        visit.setPet(pet);
321	        this.clinicService.saveVisit(visit);
322	        VisitDto visitDto = visitMapper.toVisitDto(visit);
323	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
324	            .buildAndExpand(visit.getId()).toUri());
325	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
326	    }
327	
328	
329	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
330	    @Override
331	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
332	        Owner owner = this.clinicService.findOwnerById(ownerId);
333	        if (owner != null) {
334	            Pet pet = owner.getPet(petId);
335	            if (pet != null) {
336	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
337	            }
338	        }
339	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
340	    }
341	}
