219	        HttpStatus status = HttpStatus.BAD_REQUEST;
220	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
221	        detail.setProperty("errors", List.of("email"));
222	        return ResponseEntity.status(status).body(detail);
223	    }
224	
225	    /**
226	     * Handles {@link DuplicateTelephoneException} raised on create when the supplied telephone,
227	     * after normalization, is already used by another owner. Returns a 409 Conflict whose body
228	     * carries an {@code errors} array naming the {@code telephone} field.
229	     *
230	     * @param e The {@link DuplicateTelephoneException} to be handled
231	     * @param request {@link HttpServletRequest} object referring to the current request.
232	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
233	     */
234	    @ExceptionHandler(DuplicateTelephoneException.class)
235	    @ResponseBody
236	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
237	        HttpStatus status = HttpStatus.CONFLICT;
238	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
239	        detail.setProperty("errors", List.of("telephone"));
240	        return ResponseEntity.status(status).body(detail);
241	    }
